package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.PaymentService; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@Tag(name="Pagos") @RestController @RequestMapping("/api/Pagos") public class PaymentController {private final PaymentService s;public PaymentController(PaymentService s){this.s=s;}@Operation(summary="Consultar pagos",security=@SecurityRequirement(name="bearerAuth"))@GetMapping public Object list(@AuthenticationPrincipal Jwt j){return (ReservationController.role(j).equals("CLIENTE")?s.byUser(ReservationController.id(j)):s.all()).stream().map(ApiResponses::payment).toList();}@Operation(summary="Registrar pago",description="Comprueba que la reserva pertenezca al usuario y evita pagos aprobados duplicados.",security=@SecurityRequirement(name="bearerAuth"))@PostMapping public Object create(@AuthenticationPrincipal Jwt j,@Valid@RequestBody Requests.Payment r){var x=s.create(ReservationController.id(j),r);return Map.of("mensaje","Pago realizado correctamente.","pago",ApiResponses.payment(x.payment()),"reserva",ApiResponses.reservation(x.reservation()));}@Operation(summary="Cambiar estado de pago",security=@SecurityRequirement(name="bearerAuth"))@PutMapping("/{id}/estado")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object update(@PathVariable int id,@Valid@RequestBody Requests.PaymentStatus r){var x=s.updateStatus(id,r);return Map.of("mensaje","Estado del pago actualizado correctamente.","pago",ApiResponses.payment(x.payment()),"reserva",ApiResponses.reservation(x.reservation()));}}
